class BugSearchEngine:
    """BUG知识库搜索引擎 - TF-IDF + 余弦相似度"""
    def __init__(self, knowledge_base_path: Path):
        self.bugs: List[Dict] = []
        self.vectorizer = TfidfVectorizer(tokenizer=self._tokenize, max_features=5000, ngram_range=(1, 2))
        self.tfidf_matrix = None
        self._load_knowledge(knowledge_base_path)

    def _tokenize(self, text: str) -> List[str]:
        words = jieba.lcut(text)
        return [w for w in words if len(w.strip()) > 1 and not re.match(r'^[\\W_]+$', w)]

    def _load_knowledge(self, path: Path):
        with open(path, "r", encoding="utf-8") as f:
            self.bugs = json.load(f)
        documents = [f"{b['category']} {b['symptom']} {b['root_cause']}" for b in self.bugs]
        self.tfidf_matrix = self.vectorizer.fit_transform(documents)
        logger.info(f"知识库加载完成: {len(self.bugs)} 条BUG, 特征维度: {self.tfidf_matrix.shape[1]}")

    def search(self, query: str, top_k: int = 3) -> List[Tuple[Dict, float]]:
        if not query.strip():
            return []
        query_vec = self.vectorizer.transform([query])
        similarities = cosine_similarity(query_vec, self.tfidf_matrix).flatten()
        top_indices = similarities.argsort()[-top_k:][::-1]
        results = []
        for idx in top_indices:
            score = float(similarities[idx])
            if score > 0.01:
                results.append((self.bugs[idx], score))
        return results

class CardBuilder:
    """飞书消息卡片构建器"""
    @staticmethod
    def build_diagnosis_card(query: str, results: List[Tuple[Dict, float]]) -> Dict:
        elements = []
        if not results:
            elements.append({"tag": "markdown", "content": f"\\u672a\\u627e\\u5230\\u4e0e\\u300c{query[:50]}\\u300d\\u76f8\\u5173\\u7684BUG\\u8bb0\\u5f55\\u3002\\n\\n\\u8bf7\\u5728\\u77e5\\u8bc6\\u5e93\\u4e2d\\u624b\\u52a8\\u6dfb\\u52a0\\uff0c\\u6216\\u5c1d\\u8bd5\\u66f4\\u8be6\\u7ec6\\u7684\\u62a5\\u9519\\u63cf\\u8ff0\\u3002"})
            return {"config": {"wide_screen_mode": True}, "header": {"title": {"tag": "plain_text", "content": "BUG\\u8bca\\u65ad\\u7ed3\\u679c"}, "template": "red"}, "elements": elements}
        elements.append({"tag": "markdown", "content": f"\\u6839\\u636e\\u4f60\\u7684\\u62a5\\u9519\\u4fe1\\u606f\\uff0c\\u627e\\u5230 **{len(results)}** \\u6761\\u76f8\\u5173BUG\\u8bb0\\u5f55\\uff1a"})
        for i, (bug, score) in enumerate(results):
            match_pct = f"{score * 100:.0f}%"
            star = "\\u2b50" if score > 0.5 else ("\\ud83d\\udd36" if score > 0.2 else "\\ud83d\\udd39")
            elements.append({"tag": "hr"})
            elements.append({"tag": "markdown", "content": f"### {star} \\u5339\\u914d\\u5ea6 {match_pct} | {bug['category']}"})
            elements.append({"tag": "markdown", "content": f"**\\u62a5\\u9519\\u73b0\\u8c61**\\n{bug['symptom'][:200]}"})
            elements.append({"tag": "markdown", "content": f"**\\u6839\\u56e0\\u5206\\u6790**\\n{bug['root_cause'][:200]}"})
            elements.append({"tag": "markdown", "content": f"**\\u4fee\\u590d\\u65b9\\u6848**\\n{bug['solution'][:200]}"})
        elements.append({"tag": "hr"})
        elements.append({"tag": "note", "elements": [{"tag": "plain_text", "content": f"\\u77e5\\u8bc6\\u5e93\\u5171 {len(results)} \\u6761\\u5339\\u914d | \\u53d1\\u9001\\u300c\\u5e2e\\u52a9\\u300d\\u67e5\\u770b\\u4f7f\\u7528\\u8bf4\\u660e"}]})
        return {"config": {"wide_screen_mode": True}, "header": {"title": {"tag": "plain_text", "content": f"BUG\\u8bca\\u65ad: {query[:30]}..."}, "template": "red" if results and results[0][1] > 0.5 else "blue"}, "elements": elements}

    @staticmethod
    def build_help_card() -> Dict:
        return {"config": {"wide_screen_mode": True}, "header": {"title": {"tag": "plain_text", "content": "BUG\\u8bca\\u65ad\\u673a\\u5668\\u4eba - \\u4f7f\\u7528\\u8bf4\\u660e"}, "template": "blue"}, "elements": [{"tag": "markdown", "content": "**\\u4f7f\\u7528\\u65b9\\u6cd5**\\n\\n\\u76f4\\u63a5\\u53d1\\u9001\\u62a5\\u9519\\u4fe1\\u606f\\u6216\\u547d\\u4ee4\\u884c\\u62a5\\u9519\\uff0c\\u673a\\u5668\\u4eba\\u4f1a\\u81ea\\u52a8\\u641c\\u7d22\\u5339\\u914d\\u7684BUG\\u8bb0\\u5f55\\u5e76\\u8fd4\\u56de\\u8bca\\u65ad\\u7ed3\\u679c\\u3002\\n\\n**\\u793a\\u4f8b\\u8f93\\u5165**\\n- `\\u70b9\\u51fb\\u6309\\u94ae\\u95ea\\u9000`\\n- `UnsatisfiedLinkError: dlopen failed`\\n- `\\u95f9\\u949f\\u957f\\u630910\\u79d2\\u5173\\u4e0d\\u6389`\\n- `java.lang.SecurityException: Starting FGS`\\n- `TTS\\u8bed\\u97f3\\u64ad\\u62a5\\u65e0\\u58f0`\\n\\n**\\u56de\\u590d\\u683c\\u5f0f**\\n\\u6bcf\\u6761\\u5339\\u914d\\u7ed3\\u679c\\u5305\\u542b\\uff1a\\n1. \\u62a5\\u9519\\u73b0\\u8c61\\n2. \\u6839\\u56e0\\u5206\\u6790\\n3. \\u4fee\\u590d\\u65b9\\u6848\\n\\n**\\u63d0\\u793a**\\n\\u63cf\\u8ff0\\u8d8a\\u8be6\\u7ec6\\uff0c\\u5339\\u914d\\u8d8a\\u7cbe\\u51c6\\u3002\\u53ef\\u4ee5\\u7c98\\u8d34\\u5b8c\\u6574\\u7684\\u62a5\\u9519\\u5806\\u6808\\u3002"}, {"tag": "hr"}, {"tag": "note", "elements": [{"tag": "plain_text", "content": "\\u77e5\\u8bc6\\u5e93\\u6765\\u6e90: BUG\\u6392\\u67e5\\u65e5\\u5fd7.md | \\u5fae\\u5149\\u540c\\u884c\\u9879\\u76ee"}]}]}

