def send_feishu_message(open_id: str, content: str, msg_type: str = "interactive") -> bool:
    try:
        request = CreateMessageRequest.builder().receive_id_type("open_id").request_body(
            CreateMessageRequestBody.builder().receive_id(open_id).msg_type(msg_type).content(content).build()
        ).build()
        response = feishu_client.im.v1.message.create(request)
        if response.success():
            logger.info(f"\\u6d88\\u606f\\u53d1\\u9001\\u6210\\u529f -> {open_id}")
            return True
        else:
            logger.error(f"\\u6d88\\u606f\\u53d1\\u9001\\u5931\\u8d25: {response.code} {response.msg}")
            return False
    except Exception as e:
        logger.error(f"\\u6d88\\u606f\\u53d1\\u9001\\u5f02\\u5e38: {e}")
        return False

@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok", "bugs_loaded": len(search_engine.bugs)})

@app.route("/webhook", methods=["POST"])
def webhook():
    try:
        body = request.get_json()
        logger.info(f"\\u6536\\u5230\\u98de\\u4e66\\u56de\\u8c03: {json.dumps(body, ensure_ascii=False)[:500]}")
        if body.get("type") == "url_verification":
            return jsonify({"challenge": body.get("challenge", "")})
        event_type = body.get("header", {}).get("event_type", "")
        if event_type != "im.message.receive_v1":
            return jsonify({"code": 0})
        event = body.get("event", {})
        message = event.get("message", {})
        content_str = message.get("content", "{}")
        sender_id = event.get("sender", {}).get("sender_id", {}).get("open_id", "")
        if not sender_id:
            return jsonify({"code": 0})
        try:
            content = json.loads(content_str)
        except json.JSONDecodeError:
            content = {}
        user_text = content.get("text", "").strip()
        if not user_text:
            return jsonify({"code": 0})
        logger.info(f"\\u7528\\u6237\\u6d88\\u606f: open_id={sender_id}, text={user_text[:100]}")
        if user_text.lower() in ["\\u5e2e\\u52a9", "help", "\\u4f7f\\u7528\\u8bf4\\u660e", "?"]:
            card = CardBuilder.build_help_card()
        else:
            results = search_engine.search(user_text, top_k=3)
            card = CardBuilder.build_diagnosis_card(user_text, results)
        send_feishu_message(sender_id, json.dumps(card))
        return jsonify({"code": 0})
    except Exception as e:
        logger.error(f"Webhook\\u5904\\u7406\\u5f02\\u5e38: {e}", exc_info=True)
        return jsonify({"code": 0})

